    func test_squeeze_around_empty() {
        XCTAssertClose(Matft.squeeze(Z1), MfArray([] as [Double], mftype: .Double, shape: [0]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.squeeze(Z1)")
