    func test_broadcast_to() {
        for (name, x) in emptyVariants([0], .Double){
            XCTAssertClose(Matft.broadcast_to(x, shape: [3, 0]), MfArray([] as [Double], mftype: .Double, shape: [3, 0]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.broadcast_to(x, shape: [3, 0]) [[0], .Double] \(name)")
        }
        for (name, x) in emptyVariants([0, 4], .Double){
            XCTAssertClose(Matft.broadcast_to(x, shape: [2, 0, 4]), MfArray([] as [Double], mftype: .Double, shape: [2, 0, 4]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.broadcast_to(x, shape: [2, 0, 4]) [[0, 4], .Double] \(name)")
        }
        for (name, x) in emptyVariants([3, 0], .Double){
            XCTAssertClose(Matft.broadcast_to(x, shape: [2, 3, 0]), MfArray([] as [Double], mftype: .Double, shape: [2, 3, 0]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.broadcast_to(x, shape: [2, 3, 0]) [[3, 0], .Double] \(name)")
        }
        XCTAssertClose(Matft.broadcast_to(Z10, shape: [3, 0]), MfArray([] as [Double], mftype: .Double, shape: [3, 0]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.broadcast_to(Z10, shape: [3, 0])")
        XCTAssertClose(Matft.broadcast_to(R14, shape: [0, 4]), MfArray([] as [Double], mftype: .Double, shape: [0, 4]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.broadcast_to(R14, shape: [0, 4])")
        XCTAssertClose(Matft.broadcast_to(C31, shape: [3, 0]), MfArray([] as [Double], mftype: .Double, shape: [3, 0]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.broadcast_to(C31, shape: [3, 0])")
        XCTAssertClose(Matft.broadcast_to(C31, shape: [2, 3, 0]), MfArray([] as [Double], mftype: .Double, shape: [2, 3, 0]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.broadcast_to(C31, shape: [2, 3, 0])")
        XCTAssertClose(Matft.broadcast_to(R14, shape: [0, 4]).T, MfArray([] as [Double], mftype: .Double, shape: [4, 0]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.broadcast_to(R14, shape: [0, 4]).T")
        XCTAssertClose(Matft.broadcast_to(C31, shape: [3, 0]).to_contiguous(mforder: .Column), MfArray([] as [Double], mftype: .Double, shape: [3, 0]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.broadcast_to(C31, shape: [3, 0]).to_contiguous(mforder: .Column)")
        XCTAssertEqual((Matft.broadcast_to(C31, shape: [3, 0]).to_contiguous(mforder: .Row)).data.count, 0, "Matft.broadcast_to(C31, shape: [3, 0]).to_contiguous(mforder: .Row) data")
        for (name, x) in layoutVariants(A){
            XCTAssertClose(Matft.broadcast_to(x[1~<2], shape: [0, 4]), MfArray([] as [Double], mftype: .Double, shape: [0, 4]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.broadcast_to(x[1~<2], shape: [0, 4]) [A] \(name)")
        }
        for (name, x) in layoutVariants(A){
            XCTAssertClose(Matft.broadcast_to(x[Matft.all, 1~<2], shape: [3, 0]), MfArray([] as [Double], mftype: .Double, shape: [3, 0]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.broadcast_to(x[Matft.all, 1~<2], shape: [3, 0]) [A] \(name)")
        }
    }

    func test_clip_roll() {
        for t in [.Double, .Float] as [MfType]{
            for (name, x) in emptyVariants([0], t){
                XCTAssertClose(x.clip(min: 0.0, max: 1.0), MfArray([] as [Double], mftype: t, shape: [0]), rtol: 0, atol: 0, checkType: true, "x.clip(min: 0.0, max: 1.0) [[0]] \(t) \(name)")
