        }
        for t in [.Int, .UInt8] as [MfType]{
            for (name, x) in emptyVariants([0], t){
                XCTAssertClose(x.clip(min: 0, max: 1), MfArray([] as [Double], mftype: t, shape: [0]), rtol: 0, atol: 0, checkType: true, "x.clip(min: 0, max: 1) [[0]] \(t) \(name)")
