    func test_append_insert() {
        for (name, x) in emptyVariants([0], .Double){
            XCTAssertClose(Matft.append(x, values: V), MfArray([7.0, -3.0, 0.0, 2.0] as [Double], mftype: .Double, shape: [4]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.append(x, values: V) [[0], .Double] \(name)")
        }
        for (name, x) in emptyVariants([0], .Double){
            XCTAssertClose(Matft.append(x, value: 2.5), MfArray([2.5] as [Double], mftype: .Double, shape: [1]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.append(x, value: 2.5) [[0], .Double] \(name)")
        }
        for (name, x) in emptyVariants([0], .Double){
            XCTAssertClose(Matft.append(V, values: x), MfArray([7.0, -3.0, 0.0, 2.0] as [Double], mftype: .Double, shape: [4]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.append(V, values: x) [[0], .Double] \(name)")
        }
        for (name, x) in emptyVariants([0], .Double){
            XCTAssertClose(Matft.append(x, values: x, axis: 0), MfArray([] as [Double], mftype: .Double, shape: [0]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.append(x, values: x, axis: 0) [[0], .Double] \(name)")
