    func test_norm() {
        for (name, x) in emptyVariants([0], .Double){
            XCTAssertClose(Matft.linalg.normlp_vec(x, ord: 2), MfArray([0.0] as [Double], mftype: .Double, shape: [1]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.linalg.normlp_vec(x, ord: 2) [[0], .Double] \(name)")
