        for (name, x) in emptyVariants([0], .Double){
            XCTAssertClose(Matft.linalg.normlp_vec(x, ord: 1), MfArray([0.0] as [Double], mftype: .Double, shape: [1]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.linalg.normlp_vec(x, ord: 1) [[0], .Double] \(name)")
