        }
        for (name, x) in emptyVariants([0, 4], .Double){
            XCTAssertClose(Matft.linalg.normlp_mat(x, ord: 1), MfArray([0.0] as [Double], mftype: .Double, shape: [1]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.linalg.normlp_mat(x, ord: 1) [[0, 4], .Double] \(name)")
        }
        for (name, x) in emptyVariants([0, 4], .Double){
            XCTAssertClose(Matft.linalg.normlp_mat(x, ord: -1), MfArray([0.0] as [Double], mftype: .Double, shape: [1]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.linalg.normlp_mat(x, ord: -1) [[0, 4], .Double] \(name)")
        }
        for (name, x) in emptyVariants([2, 0, 3], .Double){
            XCTAssertClose(Matft.linalg.normfro_mat(x), MfArray([0.0, 0.0] as [Double], mftype: .Double, shape: [2]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.linalg.normfro_mat(x) [[2, 0, 3], .Double] \(name)")
        }
        for (name, x) in emptyVariants([2, 0, 3], .Double){
            XCTAssertClose(Matft.linalg.normlp_mat(x, ord: 1), MfArray([0.0, 0.0] as [Double], mftype: .Double, shape: [2]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.linalg.normlp_mat(x, ord: 1) [[2, 0, 3], .Double] \(name)")
