        XCTAssertClose(try! Matft.linalg.det(M00), MfArray([1.0] as [Double], mftype: .Double, shape: [1]), rtol: 1e-10, atol: 1e-10, checkType: true, "try! Matft.linalg.det(M00)")
        XCTAssertClose(try! Matft.linalg.det(M200), MfArray([1.0, 1.0] as [Double], mftype: .Double, shape: [2]), rtol: 1e-10, atol: 1e-10, checkType: true, "try! Matft.linalg.det(M200)")
        XCTAssertClose(try! Matft.linalg.solve(M00, b: Z0), MfArray([] as [Double], mftype: .Double, shape: [0]), rtol: 1e-10, atol: 1e-10, checkType: true, "try! Matft.linalg.solve(M00, b: Z0)")
        XCTAssertClose(try! Matft.linalg.solve(M00, b: Z03), MfArray([] as [Double], mftype: .Double, shape: [0, 3]), rtol: 1e-10, atol: 1e-10, checkType: true, "try! Matft.linalg.solve(M00, b: Z03)")
        XCTAssertClose(try! Matft.linalg.pinv(Z30), MfArray([] as [Double], mftype: .Double, shape: [0, 3]), rtol: 1e-10, atol: 1e-10, checkType: true, "try! Matft.linalg.pinv(Z30)")
        XCTAssertClose(try! Matft.linalg.pinv(Z04), MfArray([] as [Double], mftype: .Double, shape: [4, 0]), rtol: 1e-10, atol: 1e-10, checkType: true, "try! Matft.linalg.pinv(Z04)")
        XCTAssertClose(try! Matft.linalg.pinv(M00), MfArray([] as [Double], mftype: .Double, shape: [0, 0]), rtol: 1e-10, atol: 1e-10, checkType: true, "try! Matft.linalg.pinv(M00)")
        XCTAssertEqual((try! Matft.linalg.eigen(M00).valRe).shape, [0], "try! Matft.linalg.eigen(M00).valRe")
        XCTAssertEqual((try! Matft.linalg.eigen(M00).rvecRe).shape, [0, 0], "try! Matft.linalg.eigen(M00).rvecRe")
