        XCTAssertEqual((try! Matft.linalg.svd(M00, full_matrices: true).v).shape, [0, 0], "try! Matft.linalg.svd(M00, full_matrices: true).v")
        XCTAssertEqual((try! Matft.linalg.svd(M00, full_matrices: true).rt).shape, [0, 0], "try! Matft.linalg.svd(M00, full_matrices: true).rt")
        XCTAssertClose(try! Matft.linalg.svd(M00, full_matrices: false).s, MfArray([] as [Double], mftype: .Double, shape: [0]), rtol: 1e-10, atol: 1e-10, checkType: true, "try! Matft.linalg.svd(M00, full_matrices: false).s")
        XCTAssertEqual((try! Matft.linalg.svd(M00, full_matrices: false).v).shape, [0, 0], "try! Matft.linalg.svd(M00, full_matrices: false).v")
        XCTAssertEqual((try! Matft.linalg.svd(M00, full_matrices: false).rt).shape, [0, 0], "try! Matft.linalg.svd(M00, full_matrices: false).rt")
