    func test_fft() {
        for (name, x) in emptyVariants([3, 0], .Double){
            XCTAssertEqual((Matft.fft.rfft(x, axis: 0)).shape, [2, 0], "Matft.fft.rfft(x, axis: 0) [[3, 0], .Double] \(name)")
        }
        for (name, x) in emptyVariants([0, 4], .Double){
            XCTAssertEqual((Matft.fft.rfft(x)).shape, [0, 3], "Matft.fft.rfft(x) [[0, 4], .Double] \(name)")
        }
        for (name, x) in emptyVariants([0, 4], .Double){
            XCTAssertEqual((Matft.fft.irfft(x)).shape, [0, 6], "Matft.fft.irfft(x) [[0, 4], .Double] \(name)")
        }
        for (name, x) in emptyVariants([3, 0], .Double){
            XCTAssertEqual((Matft.fft.irfft(x, axis: 0)).shape, [4, 0], "Matft.fft.irfft(x, axis: 0) [[3, 0], .Double] \(name)")
        }
        for (name, x) in emptyVariants([0], .Double){
            XCTAssertClose(Matft.fft.rfft(x, number: 4).real, MfArray([0.0, 0.0, 0.0] as [Double], mftype: .Double, shape: [3]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.fft.rfft(x, number: 4).real [[0], .Double] \(name)")
        }
        for (name, x) in emptyVariants([0], .Double){
            XCTAssertClose(Matft.fft.rfft(x, number: 4).imag!, MfArray([0.0, 0.0, 0.0] as [Double], mftype: .Double, shape: [3]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.fft.rfft(x, number: 4).imag! [[0], .Double] \(name)")
        }
        for (name, x) in emptyVariants([0], .Float){
            XCTAssertClose(Matft.fft.rfft(x, number: 4).real, MfArray([0.0, 0.0, 0.0] as [Double], mftype: .Double, shape: [3]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.fft.rfft(x, number: 4).real [[0], .Float] \(name)")
        }
        for (name, x) in emptyVariants([0], .Float){
            XCTAssertClose(Matft.fft.rfft(x, number: 4).imag!, MfArray([0.0, 0.0, 0.0] as [Double], mftype: .Double, shape: [3]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.fft.rfft(x, number: 4).imag! [[0], .Float] \(name)")
        }
        for (name, x) in layoutVariants(V){
