        }
        for (name, x) in layoutVariants(A){
            XCTAssertClose(Matft.fft.irfft(x, number: 5, axis: 0), MfArray([4.6000000000000005, 4.6000000000000005, 2.0, 5.800000000000001, -0.4, -0.05835921350012612, -1.065247584249853, -1.647213595499958, -0.4, -2.741640786499874, 2.0652475842498528, -0.7527864045000421, -0.4, -2.741640786499874, 2.0652475842498528, -0.7527864045000421, -0.4, -0.05835921350012612, -1.065247584249853, -1.647213595499958] as [Double], mftype: .Double, shape: [5, 4]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.fft.irfft(x, number: 5, axis: 0) [A] \(name)")
        }
    }

