    }

    #if !os(WASI)
    func test_complex() {
        do {
            let z = MfArray(real: MfArray([] as [Double], mftype: .Double, shape: [3, 0]), imag: MfArray([] as [Double], mftype: .Double, shape: [3, 0]))
            XCTAssertTrue(z.isComplex, "MfArray(real: MfArray([] as [Double], mftype: .Double, shape: [3, 0]), imag: MfArray([] as [Double], mftype: .Double, shape: [3, 0]))")
            XCTAssertEqual((z.T).shape, [0, 3], "z.T Double [3, 0]")
            XCTAssertTrue((z.T).isComplex, "z.T Double [3, 0]")
            XCTAssertEqual((Matft.deepcopy(z)).shape, [3, 0], "Matft.deepcopy(z) Double [3, 0]")
            XCTAssertTrue((Matft.deepcopy(z)).isComplex, "Matft.deepcopy(z) Double [3, 0]")
            XCTAssertEqual((z.to_contiguous(mforder: .Column)).shape, [3, 0], "z.to_contiguous(mforder: .Column) Double [3, 0]")
            XCTAssertTrue((z.to_contiguous(mforder: .Column)).isComplex, "z.to_contiguous(mforder: .Column) Double [3, 0]")
            XCTAssertEqual((z.flatten()).shape, [0], "z.flatten() Double [3, 0]")
            XCTAssertTrue((z.flatten()).isComplex, "z.flatten() Double [3, 0]")
            XCTAssertEqual((z.reshape([-1])).shape, [0], "z.reshape([-1]) Double [3, 0]")
            XCTAssertTrue((z.reshape([-1])).isComplex, "z.reshape([-1]) Double [3, 0]")
            XCTAssertEqual((z[Matft.reverse]).shape, [3, 0], "z[Matft.reverse] Double [3, 0]")
            XCTAssertTrue((z[Matft.reverse]).isComplex, "z[Matft.reverse] Double [3, 0]")
            XCTAssertEqual((z.astype(.Double)).shape, [3, 0], "z.astype(.Double) Double [3, 0]")
            XCTAssertTrue((z.astype(.Double)).isComplex, "z.astype(.Double) Double [3, 0]")
            XCTAssertEqual((-z).shape, [3, 0], "-z Double [3, 0]")
            XCTAssertTrue((-z).isComplex, "-z Double [3, 0]")
            XCTAssertEqual((z + z).shape, [3, 0], "z + z Double [3, 0]")
            XCTAssertTrue((z + z).isComplex, "z + z Double [3, 0]")
        }
        do {
            let z = MfArray(real: MfArray([] as [Double], mftype: .Double, shape: [0, 4]), imag: MfArray([] as [Double], mftype: .Double, shape: [0, 4]))
            XCTAssertTrue(z.isComplex, "MfArray(real: MfArray([] as [Double], mftype: .Double, shape: [0, 4]), imag: MfArray([] as [Double], mftype: .Double, shape: [0, 4]))")
            XCTAssertEqual((z.T).shape, [4, 0], "z.T Double [0, 4]")
            XCTAssertTrue((z.T).isComplex, "z.T Double [0, 4]")
            XCTAssertEqual((Matft.deepcopy(z)).shape, [0, 4], "Matft.deepcopy(z) Double [0, 4]")
            XCTAssertTrue((Matft.deepcopy(z)).isComplex, "Matft.deepcopy(z) Double [0, 4]")
            XCTAssertEqual((z.to_contiguous(mforder: .Column)).shape, [0, 4], "z.to_contiguous(mforder: .Column) Double [0, 4]")
            XCTAssertTrue((z.to_contiguous(mforder: .Column)).isComplex, "z.to_contiguous(mforder: .Column) Double [0, 4]")
            XCTAssertEqual((z.flatten()).shape, [0], "z.flatten() Double [0, 4]")
            XCTAssertTrue((z.flatten()).isComplex, "z.flatten() Double [0, 4]")
            XCTAssertEqual((z.reshape([-1])).shape, [0], "z.reshape([-1]) Double [0, 4]")
            XCTAssertTrue((z.reshape([-1])).isComplex, "z.reshape([-1]) Double [0, 4]")
            XCTAssertEqual((z[Matft.reverse]).shape, [0, 4], "z[Matft.reverse] Double [0, 4]")
            XCTAssertTrue((z[Matft.reverse]).isComplex, "z[Matft.reverse] Double [0, 4]")
            XCTAssertEqual((z.astype(.Double)).shape, [0, 4], "z.astype(.Double) Double [0, 4]")
            XCTAssertTrue((z.astype(.Double)).isComplex, "z.astype(.Double) Double [0, 4]")
