    #if !os(WASI)
    func test_complex_fancy() {
        do {
            let z = MfArray(real: MfArray([] as [Double], mftype: .Double, shape: [3, 0]), imag: MfArray([] as [Double], mftype: .Double, shape: [3, 0]))
            XCTAssertEqual(z[MfArray([0, 2])].shape, [2, 0], "complex fancy Double")
            XCTAssertEqual(z[EI].shape, [0, 0], "complex empty fancy Double")
        }
        do {
            let z = MfArray(real: A.astype(.Double), imag: (A * 2).astype(.Double))
            XCTAssertEqual(z[EI].shape, [0, 4], "complex empty fancy of non-empty Double")
            XCTAssertEqual(z[Matft.all, EI].shape, [3, 0], "complex empty fancy axis 1 Double")
        }
        do {
            let z = MfArray(real: MfArray([] as [Double], mftype: .Float, shape: [3, 0]), imag: MfArray([] as [Double], mftype: .Float, shape: [3, 0]))
            XCTAssertEqual(z[MfArray([0, 2])].shape, [2, 0], "complex fancy Float")
            XCTAssertEqual(z[EI].shape, [0, 0], "complex empty fancy Float")
        }
        do {
            let z = MfArray(real: A.astype(.Float), imag: (A * 2).astype(.Float))
            XCTAssertEqual(z[EI].shape, [0, 4], "complex empty fancy of non-empty Float")
            XCTAssertEqual(z[Matft.all, EI].shape, [3, 0], "complex empty fancy axis 1 Float")
        }
    }
    #endif
}
